package cl.bancoxyz.atmbff;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.*;import org.springframework.cloud.client.loadbalancer.LoadBalanced;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;@RestController @RequestMapping("/api/atm") public class AtmController{private final RestClient.Builder client;public AtmController(@LoadBalanced RestClient.Builder c){client=c;}@GetMapping("/balance/{accountId}") public Object balance(@PathVariable long accountId){return client.build().get().uri("http://account-service/api/accounts/{id}",accountId).retrieve().body(Object.class);}@PostMapping("/withdrawal") public ResponseEntity<Object> withdrawal(@Valid @RequestBody WithdrawalRequest r){Object out=client.build().post().uri("http://payment-service/api/payments/withdrawal").body(Map.of("customerId",r.customerId(),"accountId",r.accountId(),"amount",r.amount())).retrieve().body(Object.class);return ResponseEntity.status(HttpStatus.CREATED).body(out);}public record WithdrawalRequest(@NotNull Long customerId,@NotNull Long accountId,@NotNull @Positive BigDecimal amount){}}